    /*
     * Assign a Account
     * 
     * @param	parentId	UUID
     * @param	assignment 	Account 
     * @return	Portfolio
     */
    public Portfolio assignAccount( UUID parentId, Account assignment ) {
	    LOGGER.info("assigning Account as " + assignment.toString() );

	    Portfolio parentEntity = repository.findById( parentId ).get();
	    assignment = registry.project( Account.class, assignment.getAccountId());

	    // ------------------------------------------
		// assign the Account to the parent entity
		// ------------------------------------------ 
	    parentEntity.setAccount( assignment );

	    // ------------------------------------------
    	// save the parent entity
    	// ------------------------------------------ 
	    repository.save(parentEntity);
        
	    return parentEntity;
    }
    

	/*
	 * Unassign the Account
	 * 
	 * @param	parentId		UUID
	 * @return	Portfolio
	 */
	public Portfolio unAssignAccount( UUID parentId ) {
		Portfolio parentEntity = repository.findById(parentId).get();

		LOGGER.info("unAssigning Account on " + parentEntity.toString() );
		
	    // ------------------------------------------
		// null out the Account on the parent entithy
		// ------------------------------------------     
	    parentEntity.setAccount(null);

	    // ------------------------------------------
		// save the parent entity
		// ------------------------------------------ 
	    repository.save(parentEntity);
    
	    return parentEntity;
	}

