    /*
     * Add to the Positions
     * 
     * @param	parentID	UUID
     * @param	addTo		childType
     * @return	Portfolio
     */
    public Portfolio addToPositions( UUID parentId, Position addTo ) {
	    LOGGER.info("handling AssignPositionsToPortfolioEvent - " );
	    
	    Portfolio parentEntity = repository.findById(parentId).get();
	    Position child = registry.project( Position.class, addTo.getPositionId());
	    
	    parentEntity.getPositions().add( child );

	    // ------------------------------------------
    	// save 
    	// ------------------------------------------ 
	    repository.save(parentEntity);
        
	    return parentEntity;
    }
    

    /*
     * Remove from the Positions
     * 
     * @param	parentID	UUID
     * @param	removeFrom	childType
     * @return	Portfolio
     */
	public Portfolio removeFromPositions( UUID parentId, Position removeFrom ) {
	    LOGGER.info("handling RemovePositionsFromPortfolioEvent " );
	
	    Portfolio parentEntity = repository.findById(parentId).get();
	    Position child = registry.project( Position.class, removeFrom.getPositionId());
	    
	    parentEntity.getPositions().remove( child );
	
	    // ------------------------------------------
		// save
		// ------------------------------------------ 
	    update(parentEntity);
	    
	    return parentEntity;
	}

